from scipy.optimize import least_squares
forms={
 'logt': lambda p: p[0]+p[1]*np.log(t)+p[2]*t+p[3]*A**3*np.exp(-p[4]*t)+p[5]*A**3,
 'sqrt': lambda p: p[0]+p[1]*np.sqrt(t)+p[2]*t+p[3]*A**3*np.exp(-p[4]*t)+p[5]*A**3,
 'sat': lambda p: p[0]+p[1]*t/(1+p[2]*t)+p[3]*A**3*np.exp(-p[4]*t)+p[5]*A**3,
 'tanh': lambda p: p[0]+p[1]*np.tanh(p[2]*t)+p[3]*t+p[4]*A**3*np.exp(-p[5]*t),
 'ex2': lambda p: p[0]-p[1]*np.exp(-p[2]*t)+p[3]*t*np.exp(-p[4]*t)+p[5]*A**3*np.exp(-p[6]*t)+p[7]*t*np.exp(-p[8]*t)*A**3,
}
for nm,f in forms.items():
    best=None
    for s in [0.1,0.5,1.0]:
        p0=np.array([3,1,0.5,0.5,0.5,0.2,0.5,0.1,0.5,0.1])*s/0.5*0+np.array([3,1,0.5,0.5,0.5,0.2,0.5,0.1,0.5,0.1])
        try:
            res=least_squares(lambda p: f(p)-dA_dt,p0[:len(p0)],max_nfev=4000)
        except Exception as e:
            continue
        if best is None or res.cost<best.cost: best=res
    print(nm, np.mean(best.fun**2)/np.var(dA_dt), np.round(best.x,4))

